@startuml

class Location {
  + Address : string
}

class Driver {
  + FirstName : string
  + LastName : string
}

abstract class Vehicle {
  + VehicleNumber : string
}

class Truck extends Vehicle {
  + Weight : int
}

class Car extends Vehicle {
  + Seats : int
}

class Van extends Vehicle {}

class Order {
  + Origin : string
  + Destination : string
  + ExecutionDate : date
}

Location "1" -- "*" Driver
Location "1" -- "*" Vehicle
Location "1" -- "1" Order : origin
Location "1" -- "1" Order : destination
Driver "1" -- "0..1" Order : carries out
Driver "0..1" -- "0..1" Vehicle : drives

